// swift-tools-version:5.9
//
// Distribution package for SDK + Voice + Customization — generated by the Agentforce release
// scripts from each component's scripts/build-xcframework.sh output.
// Wrapper-pattern: each public library product is implemented by a wrapper
// target that carries a binary XCFramework plus its SPM-resolved transitive
// dependencies.
//
// All products ship from the same public SDK repo/release. AgentforceService is
// a shared BINARY dependency and is declared once. AgentforceVoice (when
// present) obtains the concrete MIAW multimedia implementation and its LiveKit
// runtime transitively through SMIMultimediaCore. AgentforceCustomization (when present) is a
// binary-on-binary consumer of the AgentforceSDK binary (itself binary-on-binary
// on AgentforceService) plus MobileCustomizationFramework.
//
// Do not hand-edit: regenerated on every SPM release. Dependency lists mirror
// the built dist manifests; a mismatch fails the release (see lib/spm.sh
// verify_combined_manifest_covers_dist).

import PackageDescription

let package = Package(
    name: "AgentforceSDK",
    defaultLocalization: "en",
    platforms: [
        .iOS(.v17)
    ],
    products: [
        .library(
            name: "AgentforceSDK",
            targets: ["AgentforceSDKTarget"]
        ),
        .library(
            name: "AgentforceVoice",
            targets: ["AgentforceVoiceTarget"]
        ),
        .library(
            name: "AgentforceCustomization",
            targets: ["AgentforceCustomizationTarget"]
        ),
    ],
    dependencies: [
        .package(url: "https://github.com/forcedotcom/SalesforceMobileInterfaces-iOS", from: "1.0.0"),
        .package(url: "https://github.com/Salesforce-Async-Messaging/SMIClientCore-iOS.swift.git", from: "1.11.0"),
        .package(url: "https://github.com/salesforce/SharedUI-iOS", .upToNextMajor(from: "1.3.1")),
        // SMIClientCore weak-links this implementation. Declaring the product
        // here turns ModalityConnection events into concrete voice sessions and
        // brings the matching LiveKit runtime without duplicate binary targets.
        .package(url: "https://github.com/Salesforce-Async-Messaging/SMIMultimediaCore-iOS.swift", exact: "1.12.0"),
        // MobileCustomizationFramework is net-new for AgentforceCustomization.
        // Pinned exact to the version the Customization XCFramework was built
        // against (its binary .swiftinterface verifies against that MCF API).
        .package(url: "https://github.com/salesforce/MobileCustomizationFramework-iOS.git", exact: "6.4.5"),
    ],
    targets: [
        .binaryTarget(
            name: "AgentforceSDK",
            url: "https://github.com/salesforce/AgentforceMobileSDK-iOS/releases/download/18.33.14-beta/AgentforceMobileSDK-262-2-spm.xcframework.zip",
            checksum: "848855b6ddc0ee304096d0eeda3cca8e3ac3df4da7cd7ee2dc99f5721702160b"
        ),
        .binaryTarget(
            name: "AgentforceVoice",
            url: "https://github.com/salesforce/AgentforceMobileSDK-iOS/releases/download/18.33.14-beta/AgentforceMobileVoice-262-2-spm.xcframework.zip",
            checksum: "5426f5ce559b056b0146730464f4dcbcc3d800212cb6ac6f1cee73ed0ab45e1e"
        ),
        .binaryTarget(
            name: "AgentforceService",
            url: "https://github.com/salesforce/AgentforceMobileSDK-iOS/releases/download/18.33.14-beta/AgentforceMobileService-262-2-spm.xcframework.zip",
            checksum: "2008d339bab393c2f15aa9dbf6803652c4c803d52514dbc857e9aa4cffe74434"
        ),
        .binaryTarget(
            name: "AgentforceCustomization",
            url: "https://github.com/salesforce/AgentforceMobileSDK-iOS/releases/download/18.33.14-beta/AgentforceMobileCustomization-262-2-spm.xcframework.zip",
            checksum: "1b439e03b8ece183f5f7995c7bc0634b1895bf954e9f58bb65e87306ef2f603d"
        ),
        .target(
            name: "AgentforceSDKTarget",
            dependencies: [
                "AgentforceSDK",
                "AgentforceService",
                // swift-markdown-ui intentionally omitted (SDK imports it as
                // @_implementationOnly; statically linked into the binary).
                .product(name: "SalesforceLogging",    package: "SalesforceMobileInterfaces-iOS"),
                .product(name: "SalesforceNavigation", package: "SalesforceMobileInterfaces-iOS"),
                .product(name: "SalesforceNetwork",    package: "SalesforceMobileInterfaces-iOS"),
                .product(name: "SalesforceUser",       package: "SalesforceMobileInterfaces-iOS"),
                .product(name: "SMIClientCore",        package: "SMIClientCore-iOS.swift"),
                .product(name: "SharedUI", package: "SharedUI-iOS"),
            ],
            path: "Sources/AgentforceSDKTarget"
        ),
        .target(
            name: "AgentforceVoiceTarget",
            dependencies: [
                "AgentforceVoice",
                "AgentforceService",
                .product(name: "SMIMultimediaCore", package: "SMIMultimediaCore-iOS.swift"),
                .product(name: "SalesforceNetwork", package: "SalesforceMobileInterfaces-iOS"),
                .product(name: "SalesforceLogging", package: "SalesforceMobileInterfaces-iOS"),
                // Surfaced transitively through the AgentforceService binary the
                // Voice XCFramework re-exports; SwiftPM's binary scan warns
                // ("missing a dependency on 'SalesforceUser'/'SalesforceNavigation'")
                // unless the wrapper declares them explicitly.
                .product(name: "SalesforceNavigation", package: "SalesforceMobileInterfaces-iOS"),
                .product(name: "SalesforceUser", package: "SalesforceMobileInterfaces-iOS"),
                .product(name: "SMIClientCore", package: "SMIClientCore-iOS.swift"),
            ],
            path: "Sources/AgentforceVoiceTarget"
        ),
        .target(
            name: "AgentforceCustomizationTarget",
            dependencies: [
                "AgentforceCustomization",
                // Binary-on-binary: Customization calls AgentforceSDK API through
                // resilient dispatch thunks that only exist because the SDK is a
